CREATE TABLE IF NOT EXISTS schema_migrations(version VARCHAR(64) PRIMARY KEY, applied_at DATETIME(6) NOT NULL);
CREATE TABLE IF NOT EXISTS classes(id CHAR(32) PRIMARY KEY, name VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS users(id CHAR(32) PRIMARY KEY, username VARCHAR(100) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role ENUM('teacher','student') NOT NULL, class_id CHAR(32) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME(6) NOT NULL, FOREIGN KEY(class_id) REFERENCES classes(id));
CREATE TABLE IF NOT EXISTS revoked_tokens(jti CHAR(32) PRIMARY KEY, expires_at DATETIME(6) NOT NULL, INDEX(expires_at));
CREATE TABLE IF NOT EXISTS audit_events(id CHAR(32) PRIMARY KEY, class_id CHAR(32) NULL, actor_id CHAR(32) NULL, occurred_at DATETIME(6) NOT NULL, operation VARCHAR(128) NOT NULL, http_status INT NOT NULL, event JSON NOT NULL, INDEX(class_id,occurred_at,id), INDEX(class_id,actor_id,occurred_at,id));
CREATE TABLE IF NOT EXISTS login_failures(fingerprint CHAR(64) PRIMARY KEY, failures INT NOT NULL, window_start DATETIME(6) NOT NULL);
CREATE TABLE IF NOT EXISTS resources(id CHAR(32) PRIMARY KEY, class_id CHAR(32) NOT NULL, created_by CHAR(32) NOT NULL, kind VARCHAR(32) NOT NULL, revision INT NOT NULL, body JSON NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, INDEX(class_id,kind,id), FOREIGN KEY(class_id) REFERENCES classes(id));
CREATE TABLE IF NOT EXISTS materials(id CHAR(32) PRIMARY KEY, class_id CHAR(32) NOT NULL, created_by CHAR(32) NOT NULL, title VARCHAR(255) NOT NULL, content LONGTEXT NOT NULL, input_hash CHAR(64) NOT NULL, task_id CHAR(32) NOT NULL, active_version VARCHAR(64) NOT NULL DEFAULT '', created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, INDEX(class_id,created_at,id));
CREATE TABLE IF NOT EXISTS tasks(id CHAR(32) PRIMARY KEY, class_id CHAR(32) NOT NULL, created_by CHAR(32) NOT NULL, material_id CHAR(32) NOT NULL UNIQUE, input_hash CHAR(64) NOT NULL, status VARCHAR(16) NOT NULL, stage VARCHAR(32) NOT NULL, attempts INT NOT NULL DEFAULT 0, delivery_count INT NOT NULL DEFAULT 0, next_run_at DATETIME(6) NOT NULL, lease_owner CHAR(32) NOT NULL DEFAULT '', lease_until DATETIME(6) NULL, fence INT NOT NULL DEFAULT 0, error_code VARCHAR(64) NOT NULL DEFAULT '', started_at DATETIME(6) NULL, finished_at DATETIME(6) NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, INDEX(status,lease_until),INDEX(class_id,status));
CREATE TABLE IF NOT EXISTS task_requests(class_id CHAR(32) NOT NULL, actor_id CHAR(32) NOT NULL, idempotency_key VARCHAR(128) NOT NULL, input_hash CHAR(64) NOT NULL, task_id CHAR(32) NOT NULL, PRIMARY KEY(class_id,actor_id,idempotency_key));
CREATE TABLE IF NOT EXISTS task_outbox(id CHAR(32) PRIMARY KEY, task_id CHAR(32) NOT NULL, kind VARCHAR(16) NOT NULL, generation INT NOT NULL, available_at DATETIME(6) NOT NULL, published_at DATETIME(6) NULL, lease_owner CHAR(32) NOT NULL DEFAULT '', lease_until DATETIME(6) NULL, publish_attempts INT NOT NULL DEFAULT 0, UNIQUE(task_id,kind,generation),INDEX(published_at,available_at,lease_until));
CREATE TABLE IF NOT EXISTS task_attempts(task_id CHAR(32) NOT NULL, attempt INT NOT NULL, started_at DATETIME(6) NOT NULL, finished_at DATETIME(6) NULL, error_code VARCHAR(64) NOT NULL DEFAULT '', PRIMARY KEY(task_id,attempt));
CREATE TABLE IF NOT EXISTS task_results(task_id CHAR(32) PRIMARY KEY, version VARCHAR(64) NOT NULL, chunk_count INT NOT NULL, completed_at DATETIME(6) NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_chunks(id CHAR(36) PRIMARY KEY, class_id CHAR(32) NOT NULL, material_id CHAR(32) NOT NULL, version VARCHAR(64) NOT NULL, chunk_index INT NOT NULL, start_char INT NOT NULL, end_char INT NOT NULL, body TEXT NOT NULL, UNIQUE(material_id,version,chunk_index),INDEX(class_id,material_id),FULLTEXT KEY chunk_text(body) WITH PARSER ngram);
CREATE TABLE IF NOT EXISTS mcp_servers(id CHAR(32) PRIMARY KEY, class_id CHAR(32) NOT NULL, name VARCHAR(32) NOT NULL, base_url VARCHAR(1024) NOT NULL, connected BOOLEAN NOT NULL DEFAULT FALSE, revision INT NOT NULL DEFAULT 1, tools JSON NOT NULL, UNIQUE(class_id,name));
CREATE TABLE IF NOT EXISTS conversations(id CHAR(32) PRIMARY KEY, class_id CHAR(32) NOT NULL, created_by CHAR(32) NOT NULL, agent_id CHAR(32) NOT NULL, title VARCHAR(100) NOT NULL, created_at DATETIME(6) NOT NULL, busy_turn CHAR(32) NOT NULL DEFAULT '', lease_until DATETIME(6) NULL, INDEX(class_id,created_by,created_at,id));
CREATE TABLE IF NOT EXISTS conversation_turns(id CHAR(32) PRIMARY KEY, conversation_id CHAR(32) NOT NULL, question TEXT NOT NULL, answer TEXT NOT NULL, status VARCHAR(16) NOT NULL, skill_name VARCHAR(100) NOT NULL DEFAULT '', citations JSON NOT NULL, tool_calls JSON NOT NULL, snapshot JSON NOT NULL, created_at DATETIME(6) NOT NULL, INDEX(conversation_id,created_at,id));
CREATE TABLE IF NOT EXISTS task_cleanup(task_id CHAR(32) PRIMARY KEY, cleaned_at DATETIME(6) NOT NULL);
